//////////////////////////////////////////////////////////////
//                       IMAGE                              //
//////////////////////////////////////////////////////////////

// Helper: Convert a particle ID into a texture coordinate
// for the particle data (Buffer A, Buffer C, Buffer D)
// Assumes that the texture width is equal to iResolution.x.
ivec2 locFromID_Image(int id, int w)
{
    return ivec2(id % w, id / w);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 res = iResolution.xy;
    ivec2 pixelCoord = ivec2(fragCoord);

    // Background color (dark)
    vec3 bgColor = vec3(0.05);

    // Retrieve candidate particle IDs from Buffer B.
    // (These were computed using the local Voronoi technique.)
    ivec4 candidateIDs = ivec4(texelFetch(iChannel1, pixelCoord, 0));

    float bestMeasure = 1e20;
    int bestID = -1;

    // Loop through the 4 candidate IDs and pick the one whose particle
    // disc most strongly contains this fragment.
    for (int i = 0; i < 4; i++)
    {
        int candID = candidateIDs[i];
        if (candID < 0) continue;

        // Get the candidate's position from Buffer A and its radius from Buffer D.
        ivec2 partCoord = locFromID_Image(candID, int(res.x));
        vec2 partPos = texelFetch(iChannel0, partCoord, 0).xy;
        float partRad = texelFetch(iChannel3, partCoord, 0).r;

        // Compute the signed distance from the fragment to the particle's boundary.
        float dist = boundaryDist(fragCoord, partPos, res);
        float measure = dist - partRad;

        // Choose the candidate with the smallest measure (most inside the disc)
        if (measure < bestMeasure)
        {
            bestMeasure = measure;
            bestID = candID;
        }
    }

    // If the best candidate shows that this fragment is inside its disc,
    // use that particle's group color (defined in the COMMON tab).
    if (bestID >= 0 && bestMeasure < 0.0)
    {
        // Determine the group for the particle using the COMMON function.
        int grp = getGroupForID(bestID);
        // Choose the corresponding group color.
        vec3 groupColor = (grp == 0) ? GROUP0_COLOR : (grp == 1 ? GROUP1_COLOR : GROUP2_COLOR);
        fragColor = vec4(groupColor, 1.0);
    }
    else
    {
        // Outside any particle – show the background.
        fragColor = vec4(bgColor, 1.0);
    }
}

//////////////////////////////////////////////////////////////
//                     COMMON TAB                           //
//////////////////////////////////////////////////////////////

#define TOTAL_PARTICLES  15000

// Percent distribution:
#define GROUP0_PERCENT   0.78
#define GROUP1_PERCENT   0.2
#define GROUP2_PERCENT   0.02

// Group min/max radius:
#define G0_RMIN  2.0
#define G0_RMAX  3.0
#define G1_RMIN  7.0
#define G1_RMAX  3.0
#define G2_RMIN  2.0
#define G2_RMAX  3.0

// Group colors:
#define GROUP0_COLOR  vec3(0.376,0.451,0.980)
#define GROUP1_COLOR  vec3(1.000,1.000,1.000)
#define GROUP2_COLOR  vec3(1.000,0.020,0.020)

// Speed and global parameters:
#define SPEED          1.00
#define FLUCT_SPEED    24.00
#define ATTRACTION_REGION   0.0
#define ATTRACTION_STRENGTH 0.0
#define GRAVITY_STRENGTH    -0.0

// If you want booleans that toggle at compile-time:
#define ALL_START_AT_MIN  0
#define SYNC_OSCILLATION  1

//----------------------------------------------------
// BOUNDARY_MODE picks boundary type for the simulation.
//    0 => Bouncing walls in x and y
//    1 => Fully periodic in x and y
//    2 => Periodic in x, bounce in y
//----------------------------------------------------
#define BOUNDARY_MODE     1

// Vertex radius from original code
#define VERTEX_RADIUS 1.5

//----------------------------------------------------------
// Hash function (IQ style)
float hash(int k)
{
    uint n = uint(k);
    n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return uintBitsToFloat((n >> 9U) | 0x3f800000U) - 1.0;
}

//----------------------------------------------------------
// Group cutoff helpers
#define GROUPCUTOFF0 (int(float(TOTAL_PARTICLES)*GROUP0_PERCENT))
#define GROUPCUTOFF1 (GROUPCUTOFF0 + int(float(TOTAL_PARTICLES)*GROUP1_PERCENT))

int getGroupCutoff0() { return GROUPCUTOFF0; }
int getGroupCutoff1() { return GROUPCUTOFF1; }

int getGroupForID(int id)
{
    if(id < GROUPCUTOFF0) return 0;
    if(id < GROUPCUTOFF1) return 1;
    return 2;
}

//----------------------------------------------------------
// boundaryDelta / boundaryDist that use an explicit `res`
// (so we avoid referencing iResolution directly here).
//   BOUNDARY_MODE=0 => no wrap, just a-b
//   BOUNDARY_MODE=1 => full 2D wrap
//   BOUNDARY_MODE=2 => wrap only horizontally
//----------------------------------------------------------
vec2 boundaryDelta(vec2 a, vec2 b, vec2 res)
{
    // The base difference:
    vec2 delta = a - b;

#if BOUNDARY_MODE == 1
    // Full 2D periodic
    delta = mod(delta + 0.5*res, res) - 0.5*res;
#elif BOUNDARY_MODE == 1
    // Only wrap horizontally
    delta.x = mod(delta.x + 0.5*res.x, res.x) - 0.5*res.x;
    // y is left as normal difference
#endif

    return delta;
}

float boundaryDist(vec2 a, vec2 b, vec2 res)
{
    return length(boundaryDelta(a, b, res));
}

//////////////////////////////////////////////////////////////
//                     BUFFER A                             //
//////////////////////////////////////////////////////////////

#ifndef LOCAL_ATTRACTION_STRENGTH
#define LOCAL_ATTRACTION_STRENGTH      1.80    // Base multiplier for the attraction force.
#endif

#ifndef LOCAL_ATTRACTION_REGION_MOD
#define LOCAL_ATTRACTION_REGION_MOD    80.0    // Constant attraction multiplier.
#endif

// Removed the smoothstep parameters as they are no longer used:
// #ifndef LOCAL_NEAR_DIST
// #define LOCAL_NEAR_DIST                0.0    
// #endif
//
// #ifndef LOCAL_FAR_DIST
// #define LOCAL_FAR_DIST                 10.0  
// #endif

#define SHOCK_COEFF              40.0  // Shock propagation constant.

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 res = iResolution.xy;  // Resolution for boundaryDelta, etc.
    ivec2 pix = ivec2(fragCoord);
    int id = pix.x + pix.y * int(res.x);

    // If out-of-range, simply copy from previous frame.
    if(id >= TOTAL_PARTICLES)
    {
        fragColor = texelFetch(iChannel0, pix, 0);
        return;
    }

    // Read our previous position and velocity.
    vec4 prev = texelFetch(iChannel0, pix, 0);
    vec2 pos = prev.xy;
    vec2 vel = prev.zw;

    // On the first frame, initialize with a random position and zero velocity.
    if(iFrame == 0)
    {
        float h1 = hash(id);
        float h2 = hash(id + 99999);
        pos = vec2(h1, h2) * res;
        vel = vec2(0.0);
    }

    // -------------------------------
    // 1) Accumulate forces.
    // -------------------------------
    vec2 force = vec2(0.0);

    // (a) Friction (damping).
    force -= vel * 0.001;

    // (b) Optional mouse repulsion.
    if(iMouse.z > 0.0)
    {
        vec2 deltaMouse = pos - iMouse.xy;
        float distMouse = length(deltaMouse) + 1e-3;
        force += deltaMouse / (distMouse * distMouse) * 10.0;
    }

    // (c) Gravity (downward).
    force += vec2(0.0, GRAVITY_STRENGTH);

    // (d) Retrieve our oscillator state from Buffer D.
    // Buffer D stores: [radius, phase, frequency, 1.0]
    vec4 selfD = texelFetch(iChannel3, pix, 0);
    float radA  = selfD.r;
    float phase = selfD.g;
    float freq  = selfD.b;
    float t = iTime * FLUCT_SPEED;
    // Determine if we are in a contracting phase.
    bool isContracting = (cos(t * freq + phase) < 0.0);

    // (e) Expanded neighbor interactions.
    // Instead of fetching only from our own cell, loop over a 3x3 block.
    ivec2 ipos = ivec2(floor(pos));
    for (int dx = -7; dx <= 7; dx++)
    {
        for (int dy = -7; dy <= 7; dy++)
        {
            // Wrap cell coordinates.
            ivec2 sampleCell = ipos + ivec2(dx, dy);
            sampleCell = ivec2((sampleCell.x + int(res.x)) % int(res.x),
                               (sampleCell.y + int(res.y)) % int(res.y));
            // Fetch the candidate neighbor IDs from Buffer B at this cell.
            ivec4 candidateIDs = ivec4(texelFetch(iChannel1, sampleCell, 0));
            // Loop over the 4 candidates in this cell.
            for (int j = 0; j < 4; j++)
            {
                int cid = candidateIDs[j];
                if(cid < 0 || cid == id) continue;

                // Get the candidate's pixel coordinate in Buffer A.
                ivec2 cpos = ivec2(cid % int(res.x), cid / int(res.x));
                vec4 neighborData = texelFetch(iChannel0, cpos, 0);
                vec2 otherPos = neighborData.xy;
                vec2 otherVel = neighborData.zw;
                // Get the candidate's radius from Buffer D.
                vec4 neighborD = texelFetch(iChannel3, cpos, 0);
                float radB = neighborD.r;

                // Compute the boundary-aware delta and distance.
                vec2 delta = boundaryDelta(pos, otherPos, res);
                float dist = length(delta) + 1e-6;
                vec2 dir = delta / dist;
                // Edge-to-edge gap.
                float edgeDist = dist - (radA + radB);

                // --- Compute default (repulsive) forces ---
                float repulsionFactor = 475.0 / (dist * dist * dist);
                vec2 repulsionForce = delta * repulsionFactor;

                // Overlap correction.
                float overlap = (radA + radB) - dist;
                vec2 overlapForce = vec2(0.0);
                if(overlap > 0.0)
                {
                    float overlapExtra = 475.0 * overlap;
                    overlapForce = dir * overlapExtra;
                }

                // Start with default neighbor force.
                vec2 neighborForce = repulsionForce + overlapForce;

                // --- If contracting, add attraction ---
                if(isContracting)
                {
                    // Use a constant attraction factor (removing smoothstep modulation).
                    float regionFactor = LOCAL_ATTRACTION_REGION_MOD;
                    // Attraction force pulls toward the neighbor.
                    vec2 attractionForce = -dir * (LOCAL_ATTRACTION_STRENGTH * regionFactor);

                    // Optionally, dampen default repulsion during contraction.
                    float dampedRepulsionFactor = repulsionFactor * 0.2;
                    repulsionForce = delta * dampedRepulsionFactor;

                    // Recombine forces.
                    neighborForce = repulsionForce + overlapForce + attractionForce;
                }

                // Accumulate this neighbor's force.
                force += neighborForce;

                // --- Shock propagation correction ---
                vec2 n = dir;
                float relVel = dot(vel - otherVel, n);
                if(relVel < 0.0)
                {
                    force += n * (SHOCK_COEFF * (-relVel));
                }
            }
        }
    }

    // -------------------------------
    // 2) Integrate and apply boundary conditions.
    // -------------------------------
    vel += force;
    float spd = length(vel);
    if(spd > SPEED)
    {
        vel *= (SPEED / spd);
    }
    pos += vel;

#if BOUNDARY_MODE == 1
    // Fully periodic.
    pos = mod(pos, res);
    if(pos.x < 0.0) pos.x += res.x;
    if(pos.y < 0.0) pos.y += res.y;
#elif BOUNDARY_MODE == 2
    // Periodic in x, bouncing in y.
    pos.x = mod(pos.x, res.x);
    if(pos.x < 0.0) pos.x += res.x;
    if(pos.y < radA)
    {
        pos.y = radA;
        vel.y = -vel.y;
    }
    else if(pos.y > res.y - radA - 1.0)
    {
        pos.y = res.y - radA - 1.0;
        vel.y = -vel.y;
    }
#else
    // Bouncing boundaries in both directions.
    if(pos.x < radA)
    {
        pos.x = radA;
        vel.x = -vel.x;
    }
    else if(pos.x > res.x - radA - 1.0)
    {
        pos.x = res.x - radA - 1.0;
        vel.x = -vel.x;
    }
    if(pos.y < radA)
    {
        pos.y = radA;
        vel.y = -vel.y;
    }
    else if(pos.y > res.y - radA - 1.0)
    {
        pos.y = res.y - radA - 1.0;
        vel.y = -vel.y;
    }
#endif

    fragColor = vec4(pos, vel);
}

//////////////////////////////////////////////////////////////
//                     BUFFER B                             //
//////////////////////////////////////////////////////////////

// insertion sort utility
void insertion_sort(inout ivec4 i, inout vec4 d, int newID, float newVal)
{
    // i = ID array, d = distance array
    // We compare newVal with d[0..3] and insert if smaller
    for(int idx=0; idx<4; idx++){
        if(i[idx] == newID){
            // if it's already in the list, only update if newVal < d[idx]
            if(newVal < d[idx]){
                d[idx] = newVal;
                // bubble up
                for(int k=idx; k>0 && d[k]<d[k-1]; k--){
                    // swap IDs
                    int tmpI = i[k];
                    i[k] = i[k-1];
                    i[k-1] = tmpI;
                    // swap dists
                    float tmpD = d[k];
                    d[k] = d[k-1];
                    d[k-1] = tmpD;
                }
            }
            return;
        }
    }
    // normal insertion if not duplicate
    if(newVal < d[0]){
        i = ivec4(newID, i[0], i[1], i[2]);
        d = vec4(newVal, d[0], d[1], d[2]);
    } else if(newVal < d[1]){
        i = ivec4(i[0], newID, i[1], i[2]);
        d = vec4(d[0], newVal, d[1], d[2]);
    } else if(newVal < d[2]){
        i = ivec4(i[0], i[1], newID, i[2]);
        d = vec4(d[0], d[1], newVal, d[2]);
    } else if(newVal < d[3]){
        i = ivec4(i[0], i[1], i[2], newID);
        d = vec4(d[0], d[1], d[2], newVal);
    }
}

// read the old nearest-IDs from ourselves (previous frame)
ivec4 getClosestPrev(ivec2 c)
{
    return ivec4(texelFetch(iChannel1, c, 0));
}

// turn an ID -> location in Buffer A texture
ivec2 locFromID(int id, int width)
{
    return ivec2(id % width, id / width);
}

// measure = (distance - radius) for Minkowski offset
float measureParticle(int id, vec2 fragCoord, vec2 res)
{
    if(id < 0) return 1e20;
    int width = int(res.x);
    ivec2 cpos = locFromID(id, width);

    // read (pos,vel) from Buffer A
    vec2 p = texelFetch(iChannel0, cpos, 0).xy;
    // read radius from D
    float rad = texelFetch(iChannel3, cpos, 0).r;

    vec2 d = boundaryDelta(p, fragCoord, res);
    float dist = length(d);
    return dist - rad;
}

// We'll wrap in x/y for reading from B so we can do the 3x3 neighbor
ivec2 wrapCoords(ivec2 c, ivec2 res)
{
    return ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
}

float hash( int n ); // forward-declare if needed from Common

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 resF = iResolution.xy;
    ivec2 resI = ivec2(resF);
    ivec2 c = ivec2(fragCoord);

    ivec4 newIDs  = ivec4(-1);
    vec4  newVals = vec4(1e20);

    // 1) gather from 3x3 block
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 cc = wrapCoords(c + ivec2(dx, dy), resI);
            ivec4 four = getClosestPrev(cc);
            for(int i=0; i<4; i++){
                int cand = four[i];
                float val = measureParticle(cand, fragCoord, resF);
                insertion_sort(newIDs, newVals, cand, val);
            }
        }
    }

    // 2) random candidate
    //   we incorporate iFrame for time variation
    float h = hash( c.x + c.y*resI.x + iFrame*(resI.x*resI.y) );
    int   rID  = int(h * float(TOTAL_PARTICLES));
    float rVal = measureParticle(rID, fragCoord, resF);
    insertion_sort(newIDs, newVals, rID, rVal);

    // Write top 4 IDs
    fragColor = vec4(newIDs);
}

//////////////////////////////////////////////////////////////
//                     BUFFER C                             //
//////////////////////////////////////////////////////////////
ivec2 locFromID_C(int id, int w) {
    return ivec2(id % w, id / w);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2  resF = iResolution.xy;
    ivec2 resI = ivec2(resF);
    ivec2 coord = ivec2(fragCoord);

    int id = coord.x + coord.y * resI.x;
    if(id >= TOTAL_PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    // get position/radius for this ID
    vec2 posA  = texelFetch(iChannel0, coord, 0).xy;
    float radA = texelFetch(iChannel3, coord, 0).r;

    // We'll find Minkowski-dist to the nearest other site
    float bestDist = 1e20;

    // We'll sample from B for local 3x3. (like the final pass approach)
    ivec2 base = ivec2(floor(posA));
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 sampleCoords = base + ivec2(dx, dy);
            // wrap to read B
            sampleCoords = ivec2((sampleCoords.x + resI.x) % resI.x,
                                 (sampleCoords.y + resI.y) % resI.y);

            ivec4 nb = ivec4(texelFetch(iChannel1, sampleCoords, 0));
            for(int i=0; i<4; i++){
                int nid = nb[i];
                if(nid < 0 || nid == id) continue;

                ivec2 nloc = locFromID_C(nid, resI.x);
                vec2  posB = texelFetch(iChannel0, nloc, 0).xy;
                float radB = texelFetch(iChannel3, nloc, 0).r;
                vec2  delta = boundaryDelta(posA, posB, resF);
                float dist  = length(delta);

                // Minkowski offset => dist - (radA+radB)
                float effDist = dist - (radA + radB);
                if(effDist < bestDist){
                    bestDist = effDist;
                }
            }
        }
    }

    fragColor = vec4(bestDist, 0.0, 0.0, 1.0);
}

//////////////////////////////////////////////////////////////
//                     BUFFER D                             //
//////////////////////////////////////////////////////////////

int getGroupForID(int id); // forward-declare

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 res = iResolution.xy;
    ivec2 c  = ivec2(fragCoord);
    int   id = c.x + c.y * int(res.x);

    if(id >= TOTAL_PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    // old data: [ radius, phase, freq, 1.0 ]
    vec4 oldD = texelFetch(iChannel0, c, 0);

    // Compute scale factor depending on resolution area
    float baseW    = 1280.0;
    float baseH    = 720.0;
    float baseArea = baseW * baseH;
    float newArea  = res.x * res.y;
    float scale    = sqrt(newArea / baseArea);

    // group-based min/max
    int grp = getGroupForID(id);
    float groupRMin = (grp == 0) ? G0_RMIN : (grp == 1 ? G1_RMIN : G2_RMIN);
    float groupRMax = (grp == 0) ? G0_RMAX : (grp == 1 ? G1_RMAX : G2_RMAX);

    float scaledMin = groupRMin * scale;
    float scaledMax = groupRMax * scale;

    // first frame => initialize
    if(iFrame == 0)
    {
        float s1 = hash(id + 12345);
        float s2 = hash(id + 98765);

        float phase, freq;
        if(SYNC_OSCILLATION != 0)
        {
            phase = 0.0;
            freq  = 0.5; // a chosen constant
        }
        else
        {
            phase = 6.2831853 * s1;
            freq  = mix(0.2, 1.0, s2);
        }

        float initRad;
        if(ALL_START_AT_MIN != 0)
        {
            initRad = scaledMin;
        }
        else
        {
            float rrand = hash(id + 5555);
            initRad = mix(scaledMin, scaledMax, rrand);
        }

        fragColor = vec4(initRad, phase, freq, 1.0);
    }
    else
    {
        float oldRad = oldD.r;
        float phase  = oldD.g;
        float freq   = oldD.b;

        float t  = iTime * FLUCT_SPEED;
        float s  = sin(t * freq + phase);
        float u  = 0.5 + 0.5 * s; // map -1..1 => 0..1
        float rad = mix(scaledMin, scaledMax, u);

        fragColor = vec4(rad, phase, freq, 1.0);
    }
}
